#!/usr/bin/env bash
set -euo pipefail
task_root="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")/.." && pwd)"
if [[ -f "$task_root/.turnisync-cloud.env" ]]; then
  # Generated by cloud-setup.sh; contains machine-local Java/SDK paths, no credentials.
  source "$task_root/.turnisync-cloud.env"
fi
task_arguments=("$@")
if [[ ${#task_arguments[@]} == 0 ]]; then task_arguments=(assembleBeta testDebugUnitTest); fi
cd "$task_root/android-app"
exec ./gradlew --no-daemon --console=plain \
  "-Dorg.gradle.jvmargs=-Xmx${TURNISYNC_GRADLE_HEAP:-3g} -XX:+UseParallelGC -Dfile.encoding=UTF-8" \
  -Pkotlin.compiler.execution.strategy=in-process "${task_arguments[@]}"
